#!/usr/bin/env python3
"""Generate init.recovery.<platform>.rc that loads the stock vendor modules.

Usage: gen_init_rc.py <modules.load.recovery> <out.rc>

The list comes from the stock vendor_boot ramdisk of this exact ROM, so the
load order is already the dependency order OPPO's recovery used.
"""

import sys

mods_file, out_file = sys.argv[1], sys.argv[2]

mods = []
with open(mods_file, "r", errors="replace") as fp:
    for line in fp:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        mods.append(line)

lines = [
    "# generated by gen_init_rc.py - load vendor kernel modules (display/touch/ufs/...)",
    "on early-init",
    "    mkdir /lib/modules 0755 root root 0",
    "",
    "on fs",
]
for m in mods:
    lines.append("    insmod /lib/modules/%s" % m)
lines.append("")

with open(out_file, "w") as fp:
    fp.write("\n".join(lines))
print("wrote %s with %d modules" % (out_file, len(mods)))
